<script setup lang="ts">
import { onMounted, onUnmounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import BindingFields from './BindingFields.vue'
import { domains, type Binding } from './domain-api'
import type { Operation } from './api'
const items=ref<Binding[]>([]), loading=ref(false), error=ref(''), dialog=ref(false), saving=ref(false)
const current=ref<Partial<Binding>>({kind:'panel',domain:'',auto_certificate:false}), operation=ref<Operation|null>(null), accessURL=ref('')
let timer:ReturnType<typeof setTimeout>|undefined
async function load(){loading.value=true;try{items.value=await domains.list()}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{loading.value=false}}
function edit(binding?:Binding){current.value=binding?{...binding}:{kind:'panel',resource_id:'panel',domain:'',auto_certificate:false};dialog.value=true}
async function poll(id:string){try{operation.value=await domains.operation(id);if(operation.value.status==='running'){timer=setTimeout(()=>void poll(id),2000)}else{await load();if(operation.value.status==='failed')error.value=operation.value.error;else ElMessage.success('证书已启用')}}catch(e){error.value=accessURL.value?'访问入口可能已变更，请打开下方地址确认结果。':e instanceof Error?e.message:'读取操作失败'}}
async function save(){saving.value=true;error.value='';try{const result=await domains.save(current.value);dialog.value=false;await load();if(result.operation){operation.value=result.operation;accessURL.value=result.binding.kind==='panel'?`https://${result.binding.domain}:${(await domains.access()).panel_port}`:'';void poll(result.operation.id)}else ElMessage.success('域名已保存')}catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{saving.value=false}}
async function certificate(b:Binding){error.value='';try{if(b.kind==='panel')accessURL.value=`https://${b.domain}:${(await domains.access()).panel_port}`;operation.value=await domains.certificate(b.id);void poll(operation.value.id)}catch(e){error.value=e instanceof Error?e.message:'申请失败'}}
async function remove(b:Binding){try{await ElMessageBox.confirm(`解除 ${b.domain} 的域名绑定？`,'解除绑定',{type:'warning',confirmButtonText:'解除',cancelButtonText:'取消'});await domains.remove(b.id);await load()}catch(e){if(e instanceof Error)error.value=e.message}}
onMounted(load);onUnmounted(()=>clearTimeout(timer))
const status=(value:string)=>({disabled:'未启用',requesting:'申请中',enabled:'已启用',failed:'申请失败'}[value]??value)
</script>
<template><section class="content-card"><div class="section-toolbar"><div><h3>域名与证书</h3><p class="muted">查看网站访问地址与证书状态</p></div><div><el-button @click="load">刷新</el-button><el-button type="primary" @click="edit()">绑定面板域名</el-button></div></div><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/><p v-if="accessURL"><a :href="accessURL">打开面板新地址：{{ accessURL }}</a></p><el-alert v-if="operation?.status==='running'" title="正在申请证书…" type="info" :closable="false"/><el-table v-loading="loading" :data="items" empty-text="暂无域名绑定"><el-table-column prop="domain" label="域名" min-width="180"/><el-table-column label="用途" width="100"><template #default="{row}">{{ row.kind==='panel'?'面板':row.kind==='site'?'静态网站':'容器项目' }}</template></el-table-column><el-table-column label="证书状态" min-width="120"><template #default="{row}"><el-tag :type="row.certificate_status==='enabled'?'success':row.certificate_status==='failed'?'danger':'info'">{{ status(row.certificate_status) }}</el-tag><div v-if="row.certificate_error" class="domain-error">{{ row.certificate_error }}</div></template></el-table-column><el-table-column label="到期时间" min-width="170"><template #default="{row}">{{ row.expires_at?new Date(row.expires_at).toLocaleString('zh-CN'):'—' }}</template></el-table-column><el-table-column label="操作" min-width="220"><template #default="{row}"><el-button text @click="edit(row)">编辑</el-button><el-button text @click="certificate(row)">申请证书</el-button><el-button text type="danger" @click="remove(row)">解除</el-button></template></el-table-column></el-table><el-dialog v-model="dialog" title="域名绑定" width="min(560px, 94vw)"><el-form label-position="top" @submit.prevent="save"><BindingFields :domain="current.domain??''" :auto-certificate="current.auto_certificate??false" @update:domain="current.domain=$event" @update:auto-certificate="current.auto_certificate=$event"/><p class="muted">请将域名解析到本服务器。申请证书需要公网 80 端口可达，并在面板设置中同意证书服务条款。</p><el-button type="primary" native-type="submit" :loading="saving">保存</el-button></el-form></el-dialog></section></template>
<style scoped>.section-toolbar{display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap}.section-toolbar h3{margin-bottom:0}.muted{margin:10px 0 20px}.domain-error{font-size:12px;color:var(--el-color-danger);max-width:300px;overflow-wrap:anywhere}</style>
